input.script:
first = boundary retry 2 {
    return list_tickets({ page: 1, status: "open" })
} catch err {
    return fail("LIST_FAILED", err.code + ": " + err.message)
}
remaining = for page in list.range(2, first.total_pages + 1) {
    result = boundary retry 2 { return list_tickets({ page: page, status: "open" }) } catch err {
        return fail("LIST_FAILED", err.code + ": " + err.message)
    }
    return result.items
}
listing = fold acc = first.items for page in remaining { return acc + page }
cutoff = time.parse("2026-06-03T00:00:00Z")
qualified = for record in listing {
    detail = boundary retry 2 { return get_ticket({ id: record.id }) } catch err {
        return fail("GET_FAILED", err.code + ": " + err.message)
    }
    body = detail.body if detail.body != null else ""
    created = detail.created_at if detail.created_at != null else ""
    skip if created == ""
    skip if time.parse(created) >= cutoff
    skip if not ("refund" in text.lower(body))
    return record.id
}
updated = for id in qualified {
    boundary retry 2 { return update_ticket({ id: id, priority: "high", add_tags: ["billing-escalation"] }) } catch err {
        return fail("UPDATE_FAILED", err.code + ": " + err.message)
    }
    return id
}
submission = submit_result({ answer: { escalated_ticket_ids: updated } })
return { escalated: updated, recorded: submission.recorded }
